import{_ as t,o as n,c as r,j as l,a,a2 as i}from"./chunks/framework.BkKoiSIN.js";const m=JSON.parse('{"title":"博文方法","description":"一篇文章围绕一个可检验问题，留下机制、源码与证据。","frontmatter":{"title":"博文方法","description":"一篇文章围绕一个可检验问题，留下机制、源码与证据。","kind":"overview","status":"published"},"headers":[],"relativePath":"writing/index.md","filePath":"writing/index.md"}'),d={name:"writing/index.md"};function o(u,e,s,c,h,p){return n(),r("div",null,[...e[0]||(e[0]=[l("h1",{id:"博文方法",tabindex:"-1"},[a("博文方法 "),l("a",{class:"header-anchor",href:"#博文方法","aria-label":'Permalink to "博文方法"'},"​")],-1),l("p",null,"博文用于沉淀理解、实验和判断。先明确一个问题与先修知识，再把机制、代码与证据连起来；没有完成的实验保留为计划。",-1),l("h2",{id:"深入研究的共同标准",tabindex:"-1"},[a("深入研究的共同标准 "),l("a",{class:"header-anchor",href:"#深入研究的共同标准","aria-label":'Permalink to "深入研究的共同标准"'},"​")],-1),l("p",null,"一个方法从“为什么需要它”开始，沿同一条主问题贯穿推导、实现和验证。新符号要说明含义与单位，新设计要说明它修复了哪个缺口、增加了什么代价。全文的公式、源码和实验应当解释彼此；内容多少、术语数量或论文数量不作为深度标准。",-1),l("div",{class:"reading-table",role:"group","aria-label":"表格",tabindex:"0"},[l("table",null,[l("thead",null,[l("tr",null,[l("th",null,"环节"),l("th",null,"必须回答"),l("th",null,"验收方式")])]),l("tbody",null,[l("tr",null,[l("td",null,"问题与依赖"),l("td",null,"原方案在哪个条件下遇到什么限制，先修知识是什么？"),l("td",null,"具体输入与目标；能说明少了一个前置会在哪一步卡住")]),l("tr",null,[l("td",null,"推导或不变量"),l("td",null,"为什么方法成立，哪些量变化、哪些性质必须保持？"),l("td",null,"自己复算关键步骤；系统问题给出状态转移、资源所有权和时序约束")]),l("tr",null,[l("td",null,"参考实现"),l("td",null,"最小实现是否真的体现了上述机制？"),l("td",null,"对照手算或可信reference，检查形状、边界和误差")]),l("tr",null,[l("td",null,"源码对应"),l("td",null,"真实实现里的哪段逻辑承担哪个数学或状态性质？"),l("td",null,"固定commit，追踪一条完整数据流，不只罗列类名和函数名")]),l("tr",null,[l("td",null,"对照与否证"),l("td",null,"哪种结果会推翻当前解释？"),l("td",null,"实验前写预期，加入消融、错误实现或反例；保留无效与退化")]),l("tr",null,[l("td",null,"边界与迁移"),l("td",null,"改变长度、分布、精度、并发或架构后，结论还成立吗？"),l("td",null,"至少解释并验证一个条件变化；未验证的范围明确留空")]),l("tr",null,[l("td",null,"本人能力"),l("td",null,"能否修改、预测影响、定位故障并复查？"),l("td",null,"本人讲解与一次未照搬答案的变更/排错；允许AI协作但要能判断")])])])],-1),i('<p>不同问题需要不同的正确性证据：精确数值方法检查等价与误差容限；量化和学习方法检查其目标、近似误差及任务退化；系统方法检查状态、隔离、顺序和资源回收；评测方法检查测量语义、独立性与反例。不能用一个速度数字替代这些判断。</p><p>若没有公开实现，明确区分论文描述与自己的reference，不虚构源码对应；尚不可核实的工程范围保留待验证。发现方法无收益或假设不成立也可以形成深入的限定结论，前提是解释与反例可复查。</p><h2 id="研究单位与推进顺序" tabindex="-1">研究单位与推进顺序 <a class="header-anchor" href="#研究单位与推进顺序" aria-label="Permalink to &quot;研究单位与推进顺序&quot;">​</a></h2><p>以一个边界明确的问题为研究单位，例如“固定因果模型中，增量KV计算何时与完整前向等价”。可以跨周完成，先写出解释与可否证预测，再补实现、源码和对照。前置缺口尚未解决时回到该依赖，不换另一个术语取得表面进度。</p><p>同一主题里的多个方法分别验收。理解LoRA不自动覆盖QLoRA，解释KV不自动覆盖分页、前缀共享和内核优化。暂缓的方法保持待深入，后续接续同一依赖图；不把“本阶段只认识”写成最终掌握。</p><p>示例见<a href="/inference/kv-cache">KV的等价性、状态与验证路径</a>。这是深度学习规格与参考解释，不是个人实验已完成的声明。</p><h2 id="三层内容" tabindex="-1">三层内容 <a class="header-anchor" href="#三层内容" aria-label="Permalink to &quot;三层内容&quot;">​</a></h2><p><strong>专题地图</strong>组织概念、依赖和待解决的问题；<strong>博文</strong>回答一个边界清楚的问题；<strong>项目报告</strong>连接多篇博文与实际实现。专题提纲和任务书不进入已发表文章列表。</p><h2 id="每篇文章的结构" tabindex="-1">每篇文章的结构 <a class="header-anchor" href="#每篇文章的结构" aria-label="Permalink to &quot;每篇文章的结构&quot;">​</a></h2><ol><li>问题与先修：原方案、明确缺口、研究范围与依赖。</li><li>机制与正确性：推导或不变量、适用假设、计算和资源代价。</li><li>最小参考实现：输入输出、形状/状态、手算或reference与检查。</li><li>源码对应：仓库、commit、调用路径，以及它如何兑现机制。</li><li>实验与结果：预期、否证条件、基线、变量、消融/反例、原始结果。</li><li>结论与迁移：证据范围、失败原因与条件变化后是否仍成立。</li><li>资料：靠近具体主张标注第一方论文或官方代码。</li></ol><p>原理分析、源码分析和硬件报告可以分别发表，标题与结论必须限定在实际完成的证据上。完成一篇原理文章不等于已经掌握整个主题。工具能检查格式和链接，推导、归因与理解仍需实际复核。</p><h2 id="写作与发布" tabindex="-1">写作与发布 <a class="header-anchor" href="#写作与发布" aria-label="Permalink to &quot;写作与发布&quot;">​</a></h2><p>图放在推导或实验第一次需要它的位置。流程图的箭头表示张量、数据或状态怎样传递，图注交代读图时应比较什么。数值图写明单位、样本或负载及比较条件，正文保留关键值与反例，方便读者单独核算。示例见 <a href="/foundations/transformer-architectures">整段前向与增量解码</a> 与 <a href="/evaluation/quality-systems">配对评测</a>。</p><p>草稿放在仓库drafts目录，逐步补证据；主题入口放在专题页。只有经过核对、明确标记published的article进入文章列表。发布前运行内容检查与构建，再通过source分支的原有Pages流程发布。</p><p><a href="/writing/article-template">文章模板</a> · <a href="/articles/">全部博文</a></p>',15)])])}const _=t(d,[["render",o]]);export{m as __pageData,_ as default};
